   575 inline bool EscapeString(const char *s, size_t length, std::string *_text,
   576                          bool allow_non_utf8, bool natural_utf8) {
   577   std::string &text = *_text;
   578   text += "\"";
   579   for (uoffset_t i = 0; i < length; i++) {
   580     char c = s[i];
   581     switch (c) {
   582       case '\n': text += "\\n"; break;
   583       case '\t': text += "\\t"; break;
   584       case '\r': text += "\\r"; break;
   585       case '\b': text += "\\b"; break;
   586       case '\f': text += "\\f"; break;
   587       case '\"': text += "\\\""; break;
   588       case '\\': text += "\\\\"; break;
   589       default:
   590         if (c >= ' ' && c <= '~') {
   591           text += c;
   592         } else {
   593           // Not printable ASCII data. Let's see if it's valid UTF-8 first:
   594           const char *utf8 = s + i;
   595           int ucc = FromUTF8(&utf8);
   596           if (ucc < 0) {
   597             if (allow_non_utf8) {
   598               text += "\\x";
   599               text += IntToStringHex(static_cast<uint8_t>(c), 2);
   600             } else {
   601               // There are two cases here:
   602               //
   603               // 1) We reached here by parsing an IDL file. In that case,
   604               // we previously checked for non-UTF-8, so we shouldn't reach
   605               // here.
   606               //
   607               // 2) We reached here by someone calling GenerateText()
   608               // on a previously-serialized flatbuffer. The data might have
   609               // non-UTF-8 Strings, or might be corrupt.
   610               //
   611               // In both cases, we have to give up and inform the caller
   612               // they have no JSON.
   613               return false;
   614             }
   615           } else {
   616             if (natural_utf8) {
   617               // utf8 points to past all utf-8 bytes parsed
   618               text.append(s + i, static_cast<size_t>(utf8 - s - i));
   619             } else if (ucc <= 0xFFFF) {
   620               // Parses as Unicode within JSON's \uXXXX range, so use that.
   621               text += "\\u";
   622               text += IntToStringHex(ucc, 4);
   623             } else if (ucc <= 0x10FFFF) {
   624               // Encode Unicode SMP values to a surrogate pair using two \u
   625               // escapes.
   626               uint32_t base = ucc - 0x10000;
   627               auto high_surrogate = (base >> 10) + 0xD800;
   628               auto low_surrogate = (base & 0x03FF) + 0xDC00;
   629               text += "\\u";
   630               text += IntToStringHex(high_surrogate, 4);
   631               text += "\\u";
   632               text += IntToStringHex(low_surrogate, 4);
   633             }
   634             // Skip past characters recognized.
   635             i = static_cast<uoffset_t>(utf8 - s - 1);
   636           }
   637         }
   638         break;
   639     }
   640   }
